    {
        Items.Add(entity);
        return Task.FromResult(entity);
    }

    public Task<{{ EntityName }}?> UpdateAsync({{ EntityName }} entity, CancellationToken cancellationToken = default)
    {
        var index = Items.FindIndex(item =>
            EqualityComparer<int>.Default.Equals(item.Id, entity.Id));

        if (index < 0)
        {
            return Task.FromResult<{{ EntityName }}?>(null);
        }

        Items[index] = entity;
        return Task.FromResult<{{ EntityName }}?>(entity);
    }

    public Task<bool> DeleteAsync(int id, CancellationToken cancellationToken = default)
    {
        var existing = Items.FirstOrDefault(item =>
            EqualityComparer<int>.Default.Equals(item.Id, id));

        if (existing is null)
        {
            return Task.FromResult(false);
        }

        return Task.FromResult(Items.Remove(existing));
